37	import jakarta.validation.Valid;
38	
39	import org.springframework.web.servlet.mvc.support.RedirectAttributes;
40	
41	/**
42	 * @author Juergen Hoeller
43	 * @author Ken Krebs
44	 * @author Arjen Poutsma
45	 * @author Wick Dynex
46	 */
47	@Controller
48	@RequestMapping("/owners/{ownerId}")
49	class PetController {
50	
51		private static final String VIEWS_PETS_CREATE_OR_UPDATE_FORM = "pets/createOrUpdatePetForm";
52	
53		private final OwnerRepository owners;
54	
55		private final PetTypeRepository types;
56	
57		public PetController(OwnerRepository owners, PetTypeRepository types) {
58			this.owners = owners;
59			this.types = types;
60		}
61	
62		@ModelAttribute("types")
63		public Collection<PetType> populatePetTypes() {
64			return this.types.findPetTypes();
65		}
66	
67		@ModelAttribute("owner")
68		public Owner findOwner(@PathVariable("ownerId") int ownerId) {
69			Optional<Owner> optionalOwner = this.owners.findById(ownerId);
70			Owner owner = optionalOwner.orElseThrow(() -> new IllegalArgumentException(
71					"Owner not found with id: " + ownerId + ". Please ensure the ID is correct "));
72			return owner;
73		}
74	
75		@ModelAttribute("pet")
76		public Pet findPet(@PathVariable("ownerId") int ownerId,
77				@PathVariable(name = "petId", required = false) Integer petId) {
78	
79			if (petId == null) {
80				return new Pet();
81			}
82	
83			Optional<Owner> optionalOwner = this.owners.findById(ownerId);
84			Owner owner = optionalOwner.orElseThrow(() -> new IllegalArgumentException(
85					"Owner not found with id: " + ownerId + ". Please ensure the ID is correct "));
86			return owner.getPet(petId);
87		}
88	
89		@InitBinder("owner")
90		public void initOwnerBinder(WebDataBinder dataBinder) {
91			dataBinder.setDisallowedFields("id", "*.id");
92		}
93	
94		@InitBinder("pet")
95		public void initPetBinder(WebDataBinder dataBinder) {
96			dataBinder.setValidator(new PetValidator());
97			dataBinder.setDisallowedFields("id", "*.id");
98		}
99	
100		@GetMapping("/pets/new")
101		public String initCreationForm(Owner owner, ModelMap model) {
102			Pet pet = new Pet();
103			owner.addPet(pet);
104			return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
105		}
106	
107		@PostMapping("/pets/new")
108		public String processCreationForm(Owner owner, @Valid Pet pet, BindingResult result,
109				RedirectAttributes redirectAttributes) {
110	
111			if (StringUtils.hasText(pet.getName()) && pet.isNew() && owner.getPet(pet.getName(), true) != null) {
112				result.rejectValue("name", "duplicate", "already exists");
113			}
114	
115			LocalDate currentDate = LocalDate.now();
116			if (pet.getBirthDate() != null && pet.getBirthDate().isAfter(currentDate)) {
117				result.rejectValue("birthDate", "typeMismatch.birthDate");
118			}
119	
120			if (result.hasErrors()) {
121				return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
122			}
123	
124			try {
125				owner.addPet(pet);
126				this.owners.saveAndFlush(owner);
127			}
128			catch (DataIntegrityViolationException ex) {
129				if (!isDuplicatePetNameViolation(ex)) {
130					throw ex;
131				}
132				result.rejectValue("name", "duplicate", "already exists");
133				return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
134			}
135			redirectAttributes.addFlashAttribute("message", "New Pet has been Added");
136			return "redirect:/owners/{ownerId}";
137		}
138	
139		@GetMapping("/pets/{petId}/edit")
140		public String initUpdateForm() {
141			return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
142		}
143	
144		@PostMapping("/pets/{petId}/edit")
145		public String processUpdateForm(Owner owner, @Valid Pet pet, BindingResult result,
146				RedirectAttributes redirectAttributes) {
147	
148			if (isNameTakenByAnotherPet(owner, pet)) {
149				result.rejectValue("name", "duplicate", "already exists");
150			}
151	
152			if (result.hasErrors()) {
153				return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
154			}
155	
156			try {
157				updatePetDetails(owner, pet);
158			}
159			catch (DataIntegrityViolationException ex) {
160				if (!isDuplicatePetNameViolation(ex)) {
161					throw ex;
162				}
163				result.rejectValue("name", "duplicate", "already exists");
164				return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
165			}
166			redirectAttributes.addFlashAttribute("message", "Pet details has been edited");
167			return "redirect:/owners/{ownerId}";
168		}
169	
170		private boolean isNameTakenByAnotherPet(Owner owner, Pet pet) {
171			if (!StringUtils.hasText(pet.getName())) {
172				return false;
173			}
174			Pet existingPet = owner.getPet(pet.getName(), false);
175			return existingPet != null && !Objects.equals(existingPet.getId(), pet.getId());
176		}
177	
178		/**
179		 * Updates the pet details if it exists or adds a new pet to the owner.
180		 * @param owner The owner of the pet
181		 * @param pet The pet with updated details
182		 */
183		private void updatePetDetails(Owner owner, Pet pet) {
184			Integer id = pet.getId();
185			Assert.state(id != null, "'pet.getId()' must not be null");
186			Pet existingPet = owner.getPet(id);
187			if (existingPet != null) {
188				// Update existing pet's properties
189				existingPet.setName(pet.getName());
190				existingPet.setBirthDate(pet.getBirthDate());
191				existingPet.setType(pet.getType());
192			}
193			else {
194				owner.addPet(pet);
195			}
196			this.owners.saveAndFlush(owner);
197		}
198	
199		private boolean isDuplicatePetNameViolation(DataIntegrityViolationException ex) {
200			String message = ex.getMessage();
201			return message != null && message.toLowerCase().contains("unique_owner_pet_name");
202		}
