package org.springframework.samples.petclinic.owner;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultHandlers.print;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.flash;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.model;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.redirectedUrl;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.view;

import java.time.LocalDate;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;

// TEMPORARY probe for the edit-request trace. Full context, real H2, no mocks.
@SpringBootTest
@AutoConfigureMockMvc
@Transactional
class EditRequestTraceProbeTests {

	@Autowired
	MockMvc mvc;

	@Autowired
	OwnerRepository owners;

	@Test
	void editWithFutureBirthDateIsSaved() throws Exception {
		mvc.perform(post("/owners/1/pets/1/edit").param("name", "Leo")
			.param("type", "cat")
			.param("birthDate", "2027-01-15"))
			.andDo(print())
			.andExpect(status().is3xxRedirection())
			.andExpect(redirectedUrl("/owners/1"))
			.andExpect(flash().attribute("message", "Pet details has been edited"));
		Pet leo = owners.findById(1).orElseThrow().getPet(1);
		assertThat(leo.getName()).isEqualTo("Leo");
		assertThat(leo.getBirthDate()).isEqualTo(LocalDate.of(2027, 1, 15));
	}

	@Test
	void editValidatorRunsButHasNoFutureDateRule() throws Exception {
		// blank name: PetValidator rejects name; future date gets no error
		mvc.perform(post("/owners/1/pets/1/edit").param("name", "")
			.param("type", "cat")
			.param("birthDate", "2027-01-15"))
			.andExpect(status().isOk())
			.andExpect(view().name("pets/createOrUpdatePetForm"))
			.andExpect(model().attributeHasFieldErrorCode("pet", "name", "required"))
			.andExpect(model().attributeErrorCount("pet", 1));
	}

	@Test
	void addWithFutureBirthDateIsRejected() throws Exception {
		mvc.perform(post("/owners/1/pets/new").param("name", "Probe")
			.param("type", "cat")
			.param("birthDate", "2027-01-15"))
			.andExpect(status().isOk())
			.andExpect(view().name("pets/createOrUpdatePetForm"))
			.andExpect(model().attributeHasFieldErrorCode("pet", "birthDate", "typeMismatch.birthDate"))
			.andExpect(model().attributeErrorCount("pet", 1));
		assertThat(owners.findById(1).orElseThrow().getPet("Probe")).isNull();
	}

}

